## gunicorn.conf.py

```bash
import multiprocessing

# サーバーソケット
# bind = "127.0.0.1:8000"  # TCPソケットの場合
bind = "unix:/home/nuts/WORKSPACE/edu.starton.jp/past_exam_reports/gunicorn.sock"  # Unixソ>

# プロセス数
workers = multiprocessing.cpu_count() * 2 + 1
worker_class = "gevent"  # 非同期ワーカー

# ログ設定
accesslog = "-"  # 標準出力にアクセスログを出力
errorlog = "-"   # 標準出力にエラーログを出力
loglevel = "info"

# プロセス管理
pidfile = "/tmp/gunicorn.pid"
daemon = False  # systemdやsupervisorで管理する場合はFalse
```

## /etc/nginx/sites-available/past_exam_reports

```bash
server {
    listen 80;
    server_name edu.starton.jp;

    # 静的ファイルを返す
    location /past_exam_reports/ {
            alias /home/nuts/WORKSPACE/edu.starton.jp/past_exam_reports/;
            index index.html;
    }

    location / {
        proxy_pass http://unix:/home/nuts/WORKSPACE/edu.starton.jp/past_exam_reports/gunicorn.sock;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
```
